PAD_AllocateResManager = CS.CustomPAD.PAD_AllocateResManager:Get()

---@class GooglePADManager
GooglePADManager = class("GooglePADManager")
function GooglePADManager:initialize()
    self.FuncRecvMsg=nil
end

---@return GooglePADManager
function GooglePADManager:Get()
    if self._instance == nil then
        self._instance = GooglePADManager()
    end
    return self._instance
end


function GooglePADManager:OnInit(func)
    print("---   GooglePAD Start...")
    self.FuncRecvMsg = func
    self:OpenStartUI()
    PAD_AllocateResManager:Init(function(request,status)
        self:AssetPackStatusOnChange(request,status)
    end)
end

function GooglePADManager:OpenStartUI()
    if self.UIAsset==nil then
        self.UIAsset =  CS.UnityEngine.Resources.Load("assetupdata/AssetUpdate",typeof(CS.UnityEngine.GameObject))
    end
    if self.UIPrefab==nil then
        local obj = HotfixHelper:InstantiateGameObjectByObject(self.UIAsset)
        if obj then
            self.UIPrefab = obj
        end
        self:LoadUIPrefabFinish()
    end
end

function GooglePADManager:LoadUIPrefabFinish()
    self.UIView = GooglePADView()
    self.UIView:SetData(self.UIPrefab)
    self.UIView:SetStart()
end


---@param request PlayAssetPackRequest
---@param status CustomAssetPackStatus
function GooglePADManager:AssetPackStatusOnChange(request,status)
    if status == CustomAssetPackStatus.StartRetrieveAssetPack then
        print("资源开始下载 请求")
        self.request = request
        self.UIView:AssetPackUpdate(request)
    elseif status == CustomAssetPackStatus.WaitingForWifiUnAccept then
        print("玩家取消了 wifi下载")
        HotfixHelper:ApplicationQuit()
    elseif status == CustomAssetPackStatus.AssetPackError then
        print("该资源加载错误")
        self.UIView:AssetPackUpdate(request)
    elseif status == CustomAssetPackStatus.LoadSuccess then
        self.UIView:DownloadComplete(request)
    elseif status == CustomAssetPackStatus.IsDone then
        print(request.AssetPackName.." 该资源已下载过")
    elseif status == CustomAssetPackStatus.Over then
        print("PAD所有资源已处理")
        CS.UnifySDK.UnifySDKManager.Instance.IUnifySDK:OnInit()
        if self.FuncRecvMsg~=nil then
            self.FuncRecvMsg()
            self:ClearData()
        end
    end
end

function GooglePADManager:ClearData()
    if self.UIView then
        self.UIView:CloseView()
        self.UIView=nil
    end
    if self.UIPrefab then
        CS.UnityEngine.GameObject.Destroy(self.UIPrefab)
        self.UIPrefab=nil
    end
end